// S1: who owns sc_start.
//
// vsim's per-cycle loop (Simulator::run, simulator.hpp) advances the kernel
// with sc_start(period). That is only legal from sc_main, which owns the
// kernel. Under FastSim, sc_main belongs to FastSim: it calls sc_start() once
// and everything else lives inside the kernel, where advancing time is wait().
//
// So the loop has to stop naming a mechanism. This test pins the contract that
// makes that safe: the SAME loop, over the SAME model, must see the same
// cycles and the same elapsed time whichever side of the kernel drives it.
// Both phases run in one elaboration, so any difference here is real.

#include "platform/cycle_clock.hpp"

#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include <doctest.h>
#include <systemc>

namespace {

constexpr unsigned kCycles = 7;
const sc_core::sc_time kPeriod{1, sc_core::SC_NS};

// Stands in for the Verilated core: state that only moves when the kernel
// runs. An SC_METHOD on a clock edge is what the RTL actually is.
struct TickCounter : sc_core::sc_module
{
  sc_core::sc_in_clk clk{"clk"};
  unsigned ticks = 0;

  SC_HAS_PROCESS(TickCounter);
  explicit TickCounter(const sc_core::sc_module_name& name)
      : sc_core::sc_module{name}
  {
    SC_METHOD(on_edge);
    sensitive << clk.pos();
    dont_initialize();
  }

  void on_edge() { ++ticks; }
};

// One measured run of the loop: how many times round, and how much time and
// model progress that bought.
struct Run
{
  unsigned iterations = 0;
  unsigned ticks = 0;
  sc_core::sc_time elapsed{sc_core::SC_ZERO_TIME};
};

// The shape of Simulator::run(): advance one period, then look at the model and
// decide whether to stop. This function names no mechanism -- that is the point.
auto run_cycles(CycleClock& clock, const TickCounter& core, unsigned want)
  -> Run
{
  const auto base_ticks = core.ticks;
  const auto base_time = sc_core::sc_time_stamp();
  Run r;
  while (core.ticks - base_ticks < want) {
    clock.advance(kPeriod);
    ++r.iterations;
  }
  r.ticks = core.ticks - base_ticks;
  r.elapsed = sc_core::sc_time_stamp() - base_time;
  return r;
}

// Phase B's driver. The loop runs inside the kernel here, so it may not call
// sc_start; it yields with wait() instead. Gated so it runs after phase A.
struct ThreadDriver : sc_core::sc_module
{
  TickCounter& core;
  sc_core::sc_event go{"go"};
  Run result;

  SC_HAS_PROCESS(ThreadDriver);
  ThreadDriver(const sc_core::sc_module_name& name, TickCounter& core)
      : sc_core::sc_module{name}, core{core}
  {
    SC_THREAD(drive);
  }

  void drive()
  {
    sc_core::wait(go);
    ScWaitClock clock;
    result = run_cycles(clock, core, kCycles);
    sc_core::sc_stop();
  }
};

}  // namespace

TEST_CASE("a cycle loop is identical whether sc_main or an SC_THREAD drives it")
{
  sc_core::sc_clock clk{"clk", kPeriod};
  TickCounter core{"core"};
  core.clk(clk);
  ThreadDriver thread_side{"thread_side", core};

  // Phase A: sc_main owns the kernel, so the loop starts it.
  ScStartClock start_clock;
  const Run from_sc_main = run_cycles(start_clock, core, kCycles);

  // Phase B: hand the same loop to a process inside the kernel.
  thread_side.go.notify(sc_core::SC_ZERO_TIME);
  sc_core::sc_start();
  const Run from_thread = thread_side.result;

  // The loop must not care who drives it.
  CHECK(from_thread.iterations == from_sc_main.iterations);
  CHECK(from_thread.ticks == from_sc_main.ticks);
  CHECK(from_thread.elapsed == from_sc_main.elapsed);

  // ...and it must really have run, both ways. Without this a clock that
  // advances nothing would satisfy the three checks above.
  CHECK(from_sc_main.ticks == kCycles);
  CHECK(from_thread.ticks == kCycles);
  CHECK(from_sc_main.elapsed == kCycles * kPeriod);
}
