// Stands in for the Verilated core: state that only moves when the kernel
// runs. An SC_METHOD on a clock edge is what the RTL actually is.
struct TickCounter : sc_core::sc_module
{
  sc_core::sc_in_clk clk{"clk"};
  unsigned ticks = 0;

  SC_HAS_PROCESS(TickCounter);
  explicit TickCounter(const sc_core::sc_module_name& name)
      : sc_core::sc_module{name}
  {
    SC_METHOD(on_edge);
    sensitive << clk.pos();
    dont_initialize();
  }

  void on_edge() { ++ticks; }
};

// One measured run of the loop: how many times round, and how much model
// progress and elapsed time that bought.
struct Run
{
  unsigned iterations = 0;
  unsigned ticks = 0;
  sc_core::sc_time elapsed{sc_core::SC_ZERO_TIME};
};

// The shape of Simulator::run(): advance one period, then look at the model and
// decide whether to stop. This function names no mechanism -- that is the point.
// Precondition: the caller stands at an observation point (see header comment).
auto run_cycles(CycleClock& clock, const TickCounter& core, unsigned want)
  -> Run
{
  const auto base_ticks = core.ticks;
  const auto base_time = sc_core::sc_time_stamp();
  Run r;
  while (core.ticks - base_ticks < want) {
    clock.advance(kPeriod);
    ++r.iterations;
  }
  r.ticks = core.ticks - base_ticks;
  r.elapsed = sc_core::sc_time_stamp() - base_time;
